export async function runSuite(available, check) {
  if (!available) return {executed:0, passed:true};
  await check();
  return {executed:1, passed:true};
}

checks:
const {runSuite} = await import('./suite.mjs');
let calls=0;
await assert.rejects(()=>runSuite(false,async()=>{calls++}));
assert.equal(calls,0);
assert.deepEqual(await runSuite(true,async()=>{calls++}),{executed:1,passed:true});
assert.equal(calls,1);
await assert.rejects(()=>runSuite(true,async()=>{throw Error('broken')}), /broken/);

const {verdict}=await import('./verdict.mjs');
assert.equal(verdict({sha:'a',state:'success',description:'AI QA BLOCKED (env)'},'a'),'BLOCKED');
assert.equal(verdict({sha:'a',state:'success',description:'AI QA PASS: 4/4'},'a'),'PASS');
assert.equal(verdict({sha:'a',state:'failure',description:'AI QA FAIL: denied'},'a'),'FAIL');
for(const s of [null,{sha:'old',description:'AI QA PASS'},{sha:'a',state:'success'},{sha:'a',description:'AI QA PASSING'}]) assert.equal(verdict(s,'a'),'UNKNOWN');

const {money}=await import('./money.mjs'); const {receipt}=await import('./receipt.mjs');
assert.equal(receipt(1234.5),'Total: $1,234.50');
money.format=()=> 'custom'; assert.equal(receipt(1),'Total: custom');

const m=await import('./save.mjs');
for(const f of [m.save,m.autosave]) { let calls=0; const persist=x=>{calls++;return x};
for(const bad of [0,-1,1.2,NaN,Infinity,'1',null]) assert.throws(()=>f(bad,persist));
assert.equal(calls,0);assert.equal(f(7,persist),7);assert.equal(calls,1); }

const {readDocument}=await import('./documents.mjs');
const docs=[{id:'1',tenantId:'a',body:'secret'}];const saved=JSON.stringify(docs);
assert.equal(readDocument('1',{tenantId:'a'},docs),docs[0]);
for(const s of [undefined,null,{}, {tenantId:'b'}, {tenantId:''}]) assert.throws(()=>readDocument('1',s,docs));
assert.throws(()=>readDocument('2',{tenantId:'a'},docs));assert.equal(JSON.stringify(docs),saved);

