export function createHandler(send) {
 const done=new Set();
 return async id=>{if(done.has(id))return; await send(id); done.add(id);};
}

checks:
const {createHandler}=await import('./handler.mjs');
let release;let calls=0;const gate=new Promise(r=>release=r);
const handle=createHandler(async()=>{calls++;await gate});
const a=handle('x'), b=handle('x');await Promise.resolve();release();await Promise.all([a,b]);
assert.equal(calls,1);await handle('x');assert.equal(calls,1);await handle('y');assert.equal(calls,2);
let attempts=0;const retry=createHandler(async()=>{if(++attempts===1)throw Error('temporary')});
await assert.rejects(()=>retry('z'),/temporary/);await retry('z');assert.equal(attempts,2);

