export async function collect(fetchPage,maxPages=100) {
 const out=[];for(let i=0;i<maxPages;i++){const page=await fetchPage(i);out.push(...page.filter(Boolean));}return out;
}

checks:
const {collect}=await import('./pages.mjs');let calls=[];
assert.deepEqual(await collect(async i=>{calls.push(i);return [[0,false,''],[1],[]][i]}),[0,false,'',1]);assert.deepEqual(calls,[0,1,2]);
let n=0;await assert.rejects(()=>collect(async()=>{n++;return [1]},3));assert.equal(n,3);
for(const limit of [0,-1,1.2,NaN,Infinity]) await assert.rejects(()=>collect(async()=>{throw Error('must not fetch')},limit),e=>!e.message.includes('must not fetch'));
await assert.rejects(()=>collect(async()=>{throw Error('network')}),/network/);
